INSERT INTO `eb_store_product_description` (`id`,`product_id`,`description`,`type`) SELECT 900032,900032,'<h3>远山 · 蓝白花篮</h3><p>花材：蓝色绣球、白玫瑰、洋桔梗。标准款主花约24枝；加量款在标准款基础上增加约三分之一花量。</p><p>包装：手提花篮。图片为同系列花材参考图；不同规格花量、包装及花器以选择的规格说明为准。自然花材的开放度与枝形会有差异。</p><p>花语：心怀远山，前程明朗</p><p>养护：收到后斜剪根部并去除水下叶片，置于阴凉通风处，每日清洁花瓶并换水。花泥花器缓慢少量补水。</p>',0 WHERE NOT EXISTS (SELECT 1 FROM `eb_store_product_description` WHERE product_id=900032 AND type=0);
