INSERT INTO `eb_flower_product_ext` (`product_id`,`flower_materials`,`flower_language`,`occasion`,`recipient`,`color_series`,`stem_count`,`packaging`,`care_tips`,`batch_managed`) SELECT 900036,'白色洋桔梗、绿色配叶','午后有花，平凡也美好','日常','自己,家人','白绿色',10,'桌面花器','收到后斜剪根部并去除水下叶片，置于阴凉通风处，每日清洁花瓶并换水。花泥花器缓慢少量补水。',0 WHERE NOT EXISTS (SELECT 1 FROM `eb_flower_product_ext` WHERE product_id=900036);
INSERT INTO `eb_store_product_description` (`id`,`product_id`,`description`,`type`) SELECT 900036,900036,'<h3>午后 · 洋桔梗瓶插花</h3><p>花材：白色洋桔梗、绿色配叶。标准款主花约10枝；加量款在标准款基础上增加约三分之一花量。</p><p>包装：桌面花器。图片为同系列花材参考图；不同规格花量、包装及花器以选择的规格说明为准。自然花材的开放度与枝形会有差异。</p><p>花语：午后有花，平凡也美好</p><p>养护：收到后斜剪根部并去除水下叶片，置于阴凉通风处，每日清洁花瓶并换水。花泥花器缓慢少量补水。</p>',0 WHERE NOT EXISTS (SELECT 1 FROM `eb_store_product_description` WHERE product_id=900036 AND type=0);
